// modHandlers handles the events the game delivers to the mod.
type modHandlers interface {
	// Start begins the mod's active lifetime, once, before any other event.
	Start(event *StartEvent) (*StartResult, error)
	// Frame runs once per server frame while the mod asked for frames.
	Frame(event *FrameEvent) error
	// Command offers one command a player typed.
	Command(event *CommandEvent) (*CommandResult, error)
	// World follows each world load, and start when a world has already
	// loaded. Objects and bots from an earlier world are gone by then.
	World(event *WorldEvent) error
	// UiPress reports a press on a button in a player's interface.
	UiPress(event *UiPressEvent) error
	// Serve calls a service the mod serves from the host.
	Serve(event *ServiceCall) (*ServiceReply, error)
	// Damage offers one hit before the game applies it, while the mod asked
	// for damage. The mod's answer may block the hit or change its amount.
	Damage(event *DamageEvent) (*DamageResult, error)
	// Damaged reports one hit the game applied, while the mod asked for
	// damage reports. Hits arrive before the next frame.
	Damaged(event *DamagedEvent) error
	// Input reports one player's presses of watched buttons, before the next
	// frame. A block in place still withholds them from the hero.
	Input(event *InputEvent) error
	// Restored ends one RestoreHero, before the next frame.
	Restored(event *RestoredEvent) error
	// NpcsRestored ends one RestoreNpcs, before the next frame.
	NpcsRestored(event *NpcsRestoredEvent) error
	// Launch reports a watched projectile's first frame, before the next frame.
	Launch(event *LaunchEvent) error
	// Impact reports a watched projectile striking something, inside the
	// game's impact and after its own explosion. The mod's calls apply before
	// the game continues.
	Impact(event *ImpactEvent) error
	// Landed reports a hero landing under the manifest's QuakeWorld movement,
	// before the next frame.
	Landed(event *LandedEvent) error
	// SettingChanged reports a player's setting that changed outside the mod,
	// such as on the player's profile. A mod's own SetPlayerSetting reports
	// nothing.
	SettingChanged(event *SettingChangedEvent) error
}

// serveMod runs call on handlers and returns its reply.
func serveMod(handlers modHandlers, call *wasm.Call) *wasm.Reply {
	switch call.GetMethod() {
	case "Start":
		event := &StartEvent{}
		if err := event.UnmarshalVT(call.GetRequest()); err != nil {
			return &wasm.Reply{Error: err.Error()}
		}
		return answer(handlers.Start(event))
	case "Frame":
		event := &FrameEvent{}
		if err := event.UnmarshalVT(call.GetRequest()); err != nil {
			return &wasm.Reply{Error: err.Error()}
		}
		return answer(nil, handlers.Frame(event))
	case "Command":
		event := &CommandEvent{}
		if err := event.UnmarshalVT(call.GetRequest()); err != nil {
			return &wasm.Reply{Error: err.Error()}
		}
		return answer(handlers.Command(event))
	case "World":
		event := &WorldEvent{}
		if err := event.UnmarshalVT(call.GetRequest()); err != nil {
			return &wasm.Reply{Error: err.Error()}
		}
		return answer(nil, handlers.World(event))
	case "UiPress":
		event := &UiPressEvent{}
		if err := event.UnmarshalVT(call.GetRequest()); err != nil {
			return &wasm.Reply{Error: err.Error()}
		}
		return answer(nil, handlers.UiPress(event))
	case "Serve":
		event := &ServiceCall{}
		if err := event.UnmarshalVT(call.GetRequest()); err != nil {
			return &wasm.Reply{Error: err.Error()}
		}
		return answer(handlers.Serve(event))
	case "Damage":
		event := &DamageEvent{}
		if err := event.UnmarshalVT(call.GetRequest()); err != nil {
			return &wasm.Reply{Error: err.Error()}
		}
		return answer(handlers.Damage(event))
	case "Damaged":
		event := &DamagedEvent{}
		if err := event.UnmarshalVT(call.GetRequest()); err != nil {
			return &wasm.Reply{Error: err.Error()}
		}
		return answer(nil, handlers.Damaged(event))
	case "Input":
		event := &InputEvent{}
		if err := event.UnmarshalVT(call.GetRequest()); err != nil {
			return &wasm.Reply{Error: err.Error()}
		}
		return answer(nil, handlers.Input(event))
	case "Restored":
		event := &RestoredEvent{}
		if err := event.UnmarshalVT(call.GetRequest()); err != nil {
			return &wasm.Reply{Error: err.Error()}
		}
		return answer(nil, handlers.Restored(event))
	case "NpcsRestored":
		event := &NpcsRestoredEvent{}
		if err := event.UnmarshalVT(call.GetRequest()); err != nil {
			return &wasm.Reply{Error: err.Error()}
		}
		return answer(nil, handlers.NpcsRestored(event))
	case "Launch":
		event := &LaunchEvent{}
		if err := event.UnmarshalVT(call.GetRequest()); err != nil {
			return &wasm.Reply{Error: err.Error()}
		}
		return answer(nil, handlers.Launch(event))
	case "Impact":
		event := &ImpactEvent{}
		if err := event.UnmarshalVT(call.GetRequest()); err != nil {
			return &wasm.Reply{Error: err.Error()}
		}
		return answer(nil, handlers.Impact(event))
	case "Landed":
		event := &LandedEvent{}
		if err := event.UnmarshalVT(call.GetRequest()); err != nil {
			return &wasm.Reply{Error: err.Error()}
		}
		return answer(nil, handlers.Landed(event))
	case "SettingChanged":
		event := &SettingChangedEvent{}
		if err := event.UnmarshalVT(call.GetRequest()); err != nil {
			return &wasm.Reply{Error: err.Error()}
		}
		return answer(nil, handlers.SettingChanged(event))
	}
	return &wasm.Reply{Error: "the mod has no method " + call.GetMethod()}
}
